let
    подключение = Excel.Workbook(File.Contents(pSource06), null, true),
    получение_данных = подключение{[Item="Масло_регионы",Kind="Table"]}[Data],
    меняем_типы = Table.TransformColumnTypes(получение_данных,{{"Код сырья", type text}, {"Федеральный округ", type text}, {"Показатель", type text}, {"Регион", type text}, {"Дата", type date}, {"Значение", type number}}),
    пивот_таблицы = Table.Pivot(меняем_типы, List.Distinct(меняем_типы[Показатель]), "Показатель", "Значение"),
    первичный_ключ = Table.AddColumn(пивот_таблицы, "Ключ региона", each Text.Combine({[Регион], [#"Код сырья"], Date.ToText([Дата])}, "_"), type text),
    выбираем_столбцы = Table.SelectColumns(первичный_ключ,{"Код сырья", "Регион", "Дата", "Запасы на начало месяца", "Импорт", "Потребление", "Потребление на промышленные жиры", "Потребление на майонез", "Потребление на фасовку", "Потребление на комбикорма", "Прочее потребление", "Остатки на конец месяца", "Ключ региона"})
in
    выбираем_столбцы
